// Minimal Orbit Defender game
// Canvas with id="game"
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 800;
  const height = canvas.height = canvas.clientHeight || 600;

  // Game objects
  const planet = {x: width/2, y: height/2, radius: 40, health: 10};
  const ship = {angle: 0, radius: 80, size: 10, cooldown: 0};
  const asteroids = [];
  const bullets = [];
  let score = 0;
  let lastTime = 0;

  // Helper functions
  const rand = (min, max) => Math.random() * (max - min) + min;
  const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);

input.oldString:
function draw() {
    ctx.clearRect(0, 0, width, height);
    // planet
    ctx.fillStyle = '#2b8a3e';
    ctx.beginPath();
    ctx.arc(planet.x, planet.y, planet.radius, 0, Math.PI * 2);
    ctx.fill();
    // ship
    const sx = planet.x + Math.cos(ship.angle) * ship.radius;
    const sy = planet.y + Math.sin(ship.angle) * ship.radius;
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.moveTo(sx, sy);
    const tipX = sx + Math.cos(ship.angle) * ship.size;
    const tipY = sy + Math.sin(ship.angle) * ship.size;
    ctx.lineTo(tipX, tipY);
    ctx.stroke();
    // bullets
    ctx.fillStyle = '#ff0';
    bullets.forEach(b => {
      ctx.beginPath();
      ctx.arc(b.x, b.y, 3, 0, Math.PI * 2);
      ctx.fill();
    });
    // asteroids
    ctx.fillStyle = '#a52a2a';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    });
    // HUD
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    ctx.fillText('Health: ' + planet.health, 10, 40);
  }

input.newString:
function draw() {
    // Background
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, width, height);
    // Stars
    ctx.fillStyle = '#fff';
    stars.forEach(s => {
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.size, 0, Math.PI * 2);
      ctx.fill();
    });
    // Planet with radial gradient
    const planetGrad = ctx.createRadialGradient(
      planet.x - planet.radius / 3,
      planet.y - planet.radius / 3,
      planet.radius / 8,
      planet.x,
      planet.y,
      planet.radius
    );
    planetGrad.addColorStop(0, '#4caf50');
    planetGrad.addColorStop(1, '#1b5e20');
    ctx.fillStyle = planetGrad;
    ctx.beginPath();
    ctx.arc(planet.x, planet.y, planet.radius, 0, Math.PI * 2);
    ctx.fill();
    // Ship – white triangle with outline
    const sx = planet.x + Math.cos(ship.angle) * ship.radius;
    const sy = planet.y + Math.sin(ship.angle) * ship.radius;
    const tipX = sx + Math.cos(ship.angle) * ship.size * 1.5;
    const tipY = sy + Math.sin(ship.angle) * ship.size * 1.5;
    const leftX = sx + Math.cos(ship.angle + Math.PI * 0.75) * ship.size;
    const leftY = sy + Math.sin(ship.angle + Math.PI * 0.75) * ship.size;
    const rightX = sx + Math.cos(ship.angle - Math.PI * 0.75) * ship.size;
    const rightY = sy + Math.sin(ship.angle - Math.PI * 0.75) * ship.size;
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.moveTo(tipX, tipY);
    ctx.lineTo(leftX, leftY);
    ctx.lineTo(rightX, rightY);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = '#888';
    ctx.lineWidth = 1;
    ctx.stroke();
    // Bullets with glow
    ctx.shadowColor = '#ff0';
    ctx.shadowBlur = 8;
    bullets.forEach(b => {
      ctx.beginPath();
      ctx.arc(b.x, b.y, 3, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.shadowBlur = 0; // reset
    // Asteroids with rocky gradient
    asteroids.forEach(a => {
      const grad = ctx.createRadialGradient(
        a.x - a.radius / 3,
        a.y - a.radius / 3,
        a.radius / 5,
        a.x,
        a.y,
        a.radius
      );
      grad.addColorStop(0, '#b8860b');
      grad.addColorStop(1, '#5d4037');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    });
    // HUD
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    ctx.fillText('Health: ' + planet.health, 10, 40);
  }

